const lines = [];
let line;
while ((line = readLine()) !== null) lines.push(line);
const tok = lines.join(' ').split(/\s+/).filter(s => s.length).map(Number);
const n = tok[0];
const a = tok.slice(1, 1 + n), b = tok.slice(1 + n, 1 + 2 * n);
const xs = [...new Set(a)].sort((p, q) => p - q);
const m = xs.length;
const K = new Array(4 * m).fill(0), C = new Array(4 * m).fill(null);
function insert(k, c) {
  let node = 1, lo = 0, hi = m - 1;
  for (;;) {
    if (C[node] === null) { K[node] = k; C[node] = c; return; }
    const mid = (lo + hi) >> 1;
    if (k * xs[mid] + c < K[node] * xs[mid] + C[node]) {
      let t = K[node]; K[node] = k; k = t;
      t = C[node]; C[node] = c; c = t;
    }
    if (lo === hi) return;
    if (k * xs[lo] + c < K[node] * xs[lo] + C[node]) { node = 2 * node; hi = mid; }
    else if (k * xs[hi] + c < K[node] * xs[hi] + C[node]) { node = 2 * node + 1; lo = mid + 1; }
    else return;
  }
}
function query(i) {
  const x = xs[i];
  let node = 1, lo = 0, hi = m - 1, best = Infinity;
  for (;;) {
    if (C[node] !== null) best = Math.min(best, K[node] * x + C[node]);
    if (lo === hi) return best;
    const mid = (lo + hi) >> 1;
    if (i <= mid) { node = 2 * node; hi = mid; } else { node = 2 * node + 1; lo = mid + 1; }
  }
}
const index = new Map(xs.map((x, i) => [x, i]));
let dp = 0;
insert(b[0], 0);
for (let i = 1; i < n; i++) {
  dp = query(index.get(a[i]));
  insert(b[i], dp);
}
console.log(String(dp));

