import java.io.*;
import java.util.*;

public class Main {
    static long[] xs, K;
    static Long[] C;
    static int m;

    static void insert(long k, long c) {
        int node = 1, lo = 0, hi = m - 1;
        while (true) {
            if (C[node] == null) { K[node] = k; C[node] = c; return; }
            int mid = (lo + hi) / 2;
            if (k * xs[mid] + c < K[node] * xs[mid] + C[node]) {
                long t = K[node]; K[node] = k; k = t;
                t = C[node]; C[node] = c; c = t;
            }
            if (lo == hi) return;
            if (k * xs[lo] + c < K[node] * xs[lo] + C[node]) { node = 2 * node; hi = mid; }
            else if (k * xs[hi] + c < K[node] * xs[hi] + C[node]) { node = 2 * node + 1; lo = mid + 1; }
            else return;
        }
    }

    static long query(int i) {
        long x = xs[i], best = Long.MAX_VALUE;
        int node = 1, lo = 0, hi = m - 1;
        while (true) {
            if (C[node] != null) best = Math.min(best, K[node] * x + C[node]);
            if (lo == hi) return best;
            int mid = (lo + hi) / 2;
            if (i <= mid) { node = 2 * node; hi = mid; } else { node = 2 * node + 1; lo = mid + 1; }
        }
    }

    public static void main(String[] args) throws IOException {
        StreamTokenizer in = new StreamTokenizer(new BufferedInputStream(System.in));
        in.nextToken();
        int n = (int) in.nval;
        long[] a = new long[n], b = new long[n];
        for (int i = 0; i < n; i++) { in.nextToken(); a[i] = (long) in.nval; }
        for (int i = 0; i < n; i++) { in.nextToken(); b[i] = (long) in.nval; }
        xs = Arrays.stream(a).distinct().sorted().toArray();
        m = xs.length;
        K = new long[4 * m];
        C = new Long[4 * m];
        long dp = 0;
        insert(b[0], 0);
        for (int i = 1; i < n; i++) {
            dp = query(Arrays.binarySearch(xs, a[i]));
            insert(b[i], dp);
        }
        System.out.println(dp);
    }
}

