#include <bits/stdc++.h>
using namespace std;
typedef long long ll;
vector<ll> xs, K;
vector<bool> has;
vector<ll> C;
int m;

void insertLine(ll k, ll c) {
    int node = 1, lo = 0, hi = m - 1;
    while (true) {
        if (!has[node]) { has[node] = true; K[node] = k; C[node] = c; return; }
        int mid = (lo + hi) / 2;
        if (k * xs[mid] + c < K[node] * xs[mid] + C[node]) { swap(K[node], k); swap(C[node], c); }
        if (lo == hi) return;
        if (k * xs[lo] + c < K[node] * xs[lo] + C[node]) { node = 2 * node; hi = mid; }
        else if (k * xs[hi] + c < K[node] * xs[hi] + C[node]) { node = 2 * node + 1; lo = mid + 1; }
        else return;
    }
}

ll query(int i) {
    ll x = xs[i], best = LLONG_MAX;
    int node = 1, lo = 0, hi = m - 1;
    while (true) {
        if (has[node]) best = min(best, K[node] * x + C[node]);
        if (lo == hi) return best;
        int mid = (lo + hi) / 2;
        if (i <= mid) { node = 2 * node; hi = mid; } else { node = 2 * node + 1; lo = mid + 1; }
    }
}

int main() {
    int n;
    scanf("%d", &n);
    vector<ll> a(n), b(n);
    for (auto& x : a) scanf("%lld", &x);
    for (auto& x : b) scanf("%lld", &x);
    xs = a;
    sort(xs.begin(), xs.end());
    xs.erase(unique(xs.begin(), xs.end()), xs.end());
    m = xs.size();
    K.assign(4 * m, 0);
    C.assign(4 * m, 0);
    has.assign(4 * m, false);
    ll dp = 0;
    insertLine(b[0], 0);
    for (int i = 1; i < n; i++) {
        dp = query(lower_bound(xs.begin(), xs.end(), a[i]) - xs.begin());
        insertLine(b[i], dp);
    }
    printf("%lld\n", dp);
    return 0;
}
